#include <vector>

using namespace std;

class Solution {
public:
    vector<int> findBall(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        vector<int> res(n);
        for (int j = 0; j < n; ++j) {
            int col = j;
            for (int i = 0; i < m; ++i) {
                int next = col + grid[i][col];
                if (next < 0 || next >= n || grid[i][col] != grid[i][next]) {
                    col = -1;
                    break;
                }
                col = next;
            }
            res[j] = col;
        }
        return res;
    }
};
